import java.util.Scanner;

public class LoopGrowth {
    static int[] countWork(int n) {
        n = Math.max(0, n);

        int linear = 0;
        for (int i = 0; i < n; i++) {
            linear++;
        }

        int pairs = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                pairs++;
            }
        }

        int doubling = 0;
        int size = 1;
        while (size < n) {
            doubling++;
            if (size > n / 2) {
                break;
            }
            size *= 2;
        }
        return new int[]{linear, pairs, doubling};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] result = countWork(sc.nextInt());
        System.out.println("Linear: " + result[0]);
        System.out.println("Pairs: " + result[1]);
        System.out.println("Doubling: " + result[2]);
    }
}
